operation_list = {
  '1': '电信',
  '2': '联通',
  '3': '移动',
  '4': '其他运营商',
}
status_list = {
  '1': '正常',
  '2': '停机',
  '3': '销号',
  '4': '异常',
}
value_list = {
  '1': '[0,6)',
  '2': '[6,12)',
  '3': '[12,24)',
  '4': '[24,+)',
}
data = {
  'operation': '-',
  'status': '-',
  'value': '-',
  'tel_consumption_level': '-'
}
TelPeriod = env.context.get('response',{}).json().get('TelPeriod', {})
TelPeriod_operation = TelPeriod and TelPeriod.get('operation', '-')
TelPeriod_data = TelPeriod and TelPeriod.get('data', {})
TelPeriod_value = TelPeriod_data and TelPeriod_data.get('value', '-')
TelStatus = env.context.get('response',{}).json().get('TelStatus', {})
TelStatus_data = TelStatus and TelStatus.get('data', {})
TelStatus_value = TelStatus_data and TelStatus_data.get('value', '-')

for operation in operation_list.keys():
  if TelPeriod_operation and operation == TelPeriod_operation[0]:
    data.update({
      'operation': operation_list.get(operation)
    })
for status in status_list.keys():
  if TelStatus_value and status == TelStatus_value[0]:
    data.update({
      'status': status_list.get(status)
    })
for value in value_list.keys():
  if TelPeriod_value and value == TelPeriod_value[0]:
    data.update({
      'value': value_list.get(value)
    })

action = {
  'data': data,
  'code': 'Tel_Info'
}

