def handle_list(data, list, is_bank):
  month_list = ['d7', 'd15', 'm1', 'm3', 'm6', 'm12',]
  applyLoan_abnormaiTime_list = []
  name_value = ''
  for custcomer in list:
    applyLoan_abnormaiTime = {}
    for month in month_list:
      applyLoan_abnormaiTime.update({
        'allnum_'+month: applyLoan_get(data, month, 'id', is_bank, custcomer[0]) + '/' + applyLoan_get(data, month, 'cell', is_bank, custcomer[0]),
        'orgnum_'+month: applyLoan_get(data, month, 'id', is_bank, custcomer[1]) + '/' + applyLoan_get(data, month, 'cell', is_bank, custcomer[1]),
      })
    for name in name_list:
      if is_bank == 'bank'and name == 'bank_'+custcomer[0]:
        name_value = name_list.get(name)
      if is_bank == 'nbank'and name == 'nbank_'+custcomer[0]:
        name_value = name_list.get(name)
    applyLoan_abnormaiTime.update({
      'name': name_value,
    })
    applyLoan_abnormaiTime_list.append(applyLoan_abnormaiTime)
  return applyLoan_abnormaiTime_list

