month_list = ['m1', 'm2', 'm3', 'm4', 'm5', 'm6', 'm7', 'm8', 'm9', 'm10', 'm11', 'm12',]
for key in history_list:
  totalLoan_history = {}
  for month in month_list:
    totalLoan_history.update({
      month: data.get(month, {}).get('id', {}).get('nobank', {}).get(key, '-') + '/' + data.get(month, {}).get('cell', {}).get('nobank', {}).get(key, '-'),
    })
  for name in name_list.keys():
    if name == key:
      name_value = name_list.get(name)
  totalLoan_history.update({
    'name': name_value
  })
  totalLoan_history_list.append(totalLoan_history)

action = {
  'datas': totalLoan_history_list,
  'code': 'TotalLoan_History'
}

# Available variables:
#  - env: Odoo Environment on which the action is triggered
#  - model: Odoo Model of the record on which the action is triggered; is a void recordset
#  - record: record on which the action is triggered; may be void
#  - records: recordset of all records on which the action is triggered in multi-mode; may be void
#  - time, datetime, dateutil, timezone: useful Python libraries
#  - float_compare: Odoo function to compare floats based on specific precisions
#  - log: log(message, level='info'): logging function to record debug information in ir.logging table
#  - UserError: Warning Exception to use with raise
#  - Command: x2Many commands namespace
# To return an action, assign: action = {...}

infoRelation = env.context.get('response',{}).json().get('InfoRelation', {}) or {}
infoRelation_list = ['m1', 'm3', 'm6', 'm9', 'm12']
infoRelation_idCard_list = []
for key in infoRelation:
    if key not in infoRelation_list and key[0: 2] == 'id':
      infoRelation_idCard_list.append({
          'name': 'ir_' + key,
          'result': infoRelation.get(key,'') or '-'
      })
    else:
      for x_key in infoRelation.get(key, {}):
        if 'id' in x_key and 'cell' in x_key:
          id_key = x_key.find('id', 0, len(x_key)-1)
          cell_key = x_key.find('cell', 0, len(x_key)-1)
          if cell_key > id_key:
            infoRelation_idCard_list.append({
              'name': 'ir_' + key + '_' + x_key,
              'result': infoRelation.get(key, {}).get(x_key,'') or '-'
            })
        elif 'id' in x_key:
          infoRelation_idCard_list.append({
              'name': 'ir_' + key + '_' + x_key,
              'result': infoRelation.get(key, {}).get(x_key,'') or '-'
          })
        else:
          pass

action = {
  'datas': infoRelation_idCard_list,
  'code': 'InfoRelation_IdCard'
}

